                },
                onCopy: {},
                onDismiss: {
                    selectedSegment = nil
                }
            )
            .frame(minWidth: 300, minHeight: 350)
            .localizedSurface()
        }
        #endif
    }

    // MARK: - Language Selector

    private var languageSelector: some View {
        HStack(spacing: 12) {
