    if let text {
        latestTranscription = text
        if isFinal {
            deliverFinalIfNeeded()
        } else {
            onPartialResult?(text)
        }
    }

    if let error {
        // endAudio() during a normal stop surfaces a cancellation-style
        // error from the recognizer — that's not a failure.
        if isStopping {
            deliverFinalIfNeeded()
        } else {
            onStreamError?(error)
        }
    }
